buildGradleAdditions.insert:
afterEvaluate {
tasks.matching { it.name.startsWith('process') && it.name.contains('Manifest') }.all { task ->
task.doLast {
fileTree(buildDir).matching { include '**/AndroidManifest.xml' }.each { File f ->
if (f.text.contains('WRITE_EXTERNAL_STORAGE') || f.text.contains('StartupPermissions')) {
def lines = f.readLines()
def filtered = lines.findAll { !it.contains('WRITE_EXTERNAL_STORAGE') }
filtered = filtered.collect { line ->
if (line.contains('StartupPermissions')) {
return line.replaceAll('android:value="[^"]*"', 'android:value=""')
}
return line
}
f.text = filtered.join(System.lineSeparator())
}
}
}
}
}
